+	unsigned short id = __swap_cgroup_get(ci, off % SWAPFILE_CLUSTER);
+
+	return id ? mem_cgroup_from_private_id(id) : NULL;
+}
+
+static void xswap_backend_uncharge(swp_entry_t entry, unsigned int nr)
+{
